<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Warning } from '@element-plus/icons-vue'
import WorkbookWorkbench from './WorkbookWorkbench.vue'
import { deleteCashflow, deleteCashflowHistoryRecord, listCashflow, listCashflowHistory, listCashflowHistoryRecords, saveCashflow, saveCashflowHistoryRecord, type CashflowEntry, type CashflowGroup, type CashflowHistory, type CashflowHistoryRecord, type CashflowScenario, type CashflowSummary } from '../../services/personalWorkApi'

const regions = ['东区', '西区', '中区', '广东区', '未分区']
const items = ref<CashflowScenario[]>([])
const summary = ref<CashflowSummary>({ total: 0, total_receivable: 0, total_received: 0, outstanding: 0, funding_gap: 0, funding_cost: 0 })
const byRegion = ref<CashflowGroup[]>([]); const byCustomer = ref<CashflowGroup[]>([])
const history = ref<CashflowHistory | null>(null)
const workbookVisible = ref(false)
const profilesVisible = ref(false); const profileKeyword = ref('')
const historyEditorVisible = ref(false); const historyRows = ref<CashflowHistoryRecord[]>([]); const historyTotal = ref(0); const historyPage = ref(1); const historyKeyword = ref(''); const historyRegion = ref(''); const historyLoading = ref(false)
const dialog = ref(false); const detail = ref<CashflowScenario | null>(null); const detailVisible = ref(false)
const money = (value: number) => `¥${Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 2 })}`
const blankEntry = (): CashflowEntry => ({ id: '', date: '', milestone: '', receivable: 0, received: 0, procurement: 0, special_procurement: 0, reimbursement: 0, personnel: 0, other: 0, guarantee: 0 })
const blank = (): CashflowScenario => ({ id: '', project_name: '', project_code: '', region: '未分区', customer: '', owner: '', annual_rate: 0.06, note: '', entries: [blankEntry()], summary: { total_receivable: 0, total_received: 0, outstanding: 0, total_payment: 0, funding_gap: 0, funding_cost: 0, ending_cashflow: 0 }, updated_at: '' })
const form = reactive<CashflowScenario>(blank())
const filteredItems = computed(() => items.value)
const filteredCustomerProfiles = computed(() => {
  const keyword = profileKeyword.value.trim().toLowerCase()
  return (history.value?.customer_profiles || []).filter(profile => !keyword || `${profile.name} ${profile.traits.join(' ')}`.toLowerCase().includes(keyword))
})
const selectedCustomerProfile = computed(() => history.value?.customer_profiles.find(profile => profile.name === form.customer.trim()) || null)
const chartColors = ['#2b8f64', '#4478cc', '#d8902d', '#ac5eb7', '#de6c5f', '#4c9a9a']
const statusGradient = computed(() => {
  const rows = history.value?.by_status || []
  const total = rows.reduce((sum, row) => sum + row.planned, 0) || 1
  let cursor = 0
  const slices = rows.map((row, index) => { const end = cursor + row.planned / total * 100; const value = `${chartColors[index % chartColors.length]} ${cursor.toFixed(1)}% ${end.toFixed(1)}%`; cursor = end; return value })
  return `conic-gradient(${slices.join(', ') || '#e8efeb 0 100%'})`
})
const maxRegionUnpaid = computed(() => Math.max(1, ...(history.value?.by_region.map(row => row.unpaid) || [0])))
const maxYearAmount = computed(() => Math.max(1, ...(history.value?.by_year.map(row => Math.max(row.planned, row.received)) || [0])))
const formHistoryHint = computed(() => {
  const data = history.value
  if (!data?.summary.records) return ''
  const regional = data.by_region.find(row => row.name === form.region)
  const type = data.by_project_type[0]
  const regionText = regional ? `${regional.name}历史回款达成率 ${regional.received_rate}%，待回 ${money(regional.unpaid)}` : `历史整体回款达成率 ${data.summary.received_rate}%`
  const customer = selectedCustomerProfile.value
  const typeText = type ? `；建议先拆分${type.name}等关键回款节点并设定到期日` : ''
  const customerText = customer ? `；${customer.name}：${customer.recommendation}` : ''
  return regionText + typeText + customerText
})
async function load() { try { const [data, historyData] = await Promise.all([listCashflow(), listCashflowHistory()]); items.value = data.items; summary.value = data.summary; byRegion.value = data.by_region; byCustomer.value = data.by_customer; history.value = historyData } catch (e) { ElMessage.error(e instanceof Error ? e.message : '资金测算加载失败') } }
async function loadHistoryRecords(page = historyPage.value) { historyLoading.value = true; try { const data = await listCashflowHistoryRecords({ keyword: historyKeyword.value, region: historyRegion.value, page, page_size: 30 }); historyRows.value = data.items; historyTotal.value = data.total; historyPage.value = data.page } catch (e) { ElMessage.error(e instanceof Error ? e.message : '历史回款数据加载失败') } finally { historyLoading.value = false } }
function openHistoryEditor() { historyEditorVisible.value = true; loadHistoryRecords(1) }
function addHistoryRow() { historyRows.value.unshift({ id: '', region: '未分区', office: '', province: '', customer: '', project_code: '', project_name: '', project_type: '', contract_amount: 0, planned_amount: 0, received_amount: 0, status: '未回款', contract_date: '', planned_date: '', received_date: '', is_difficult: false, is_long_term: false }) }
async function saveHistoryRow(row: CashflowHistoryRecord) { try { const { item } = await saveCashflowHistoryRecord(row); Object.assign(row, item); await load(); ElMessage.success('历史回款记录已保存，分析结果已刷新') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '保存失败') } }
async function removeHistoryRow(row: CashflowHistoryRecord) { if (!row.id) { historyRows.value = historyRows.value.filter(item => item !== row); return } try { await ElMessageBox.confirm('删除后将不再参与历史规律分析，确认删除？', '删除历史记录', { type: 'warning' }); await deleteCashflowHistoryRecord(row.id); await loadHistoryRecords(); await load(); ElMessage.success('历史回款记录已删除') } catch (e) { if (e !== 'cancel') ElMessage.error(e instanceof Error ? e.message : '删除失败') } }
function open(item?: CashflowScenario) { Object.assign(form, item ? JSON.parse(JSON.stringify(item)) : blank()); if (!form.entries.length) form.entries = [blankEntry()]; dialog.value = true }
function addEntry() { form.entries.push(blankEntry()) }
function applyCustomerProfile() { const profile = selectedCustomerProfile.value; if (!profile) return; const hasContent = form.entries.some(entry => entry.date || entry.milestone || entry.receivable || entry.received); if (hasContent) return ElMessage.warning('请先清空现有资金节点后再带入客户常见回款节点'); form.entries = profile.payment_patterns.map(pattern => ({ ...blankEntry(), milestone: `${pattern.name}（历史占比 ${pattern.share}%）` })); ElMessage.success('已带入该客户的常见回款节点，请补充日期与金额') }
function useCustomerProfile(name: string) { Object.assign(form, blank(), { customer: name }); profilesVisible.value = false; dialog.value = true; applyCustomerProfile() }
function removeEntry(index: number) { if (form.entries.length > 1) form.entries.splice(index, 1) }
async function submit() { if (!form.project_name.trim()) return ElMessage.warning('请填写项目名称'); if (form.entries.some(x => !x.date)) return ElMessage.warning('请填写每个资金节点的日期'); try { await saveCashflow(form); dialog.value = false; await load(); ElMessage.success('资金测算已保存') } catch (e) { ElMessage.error(e instanceof Error ? e.message : '保存失败') } }
async function remove(id: string) { try { await ElMessageBox.confirm('删除后不可恢复，确认删除这份资金测算？', '删除资金测算', { type: 'warning' }); await deleteCashflow(id); await load(); ElMessage.success('已删除') } catch (e) { if (e !== 'cancel') ElMessage.error(e instanceof Error ? e.message : '删除失败') } }
function showDetail(item: CashflowScenario) { detail.value = item; detailVisible.value = true }
onMounted(load)
</script>

<template>
  <section class="workspace-main cashflow-main">
    <header class="cashflow-head"><div><p>经营协同 · 资金安全</p><h1>资金测算助手</h1><span>按区域、客户和项目掌握回款节奏，提前识别资金缺口与垫资成本。</span></div><div class="cashflow-head__actions"><el-button plain type="primary" @click="workbookVisible=true">完整项目测算工作簿</el-button><el-button type="primary" :icon="Plus" @click="open()">新建资金测算</el-button></div></header>
    <section class="cashflow-stats"><article><span>在测项目</span><strong>{{ summary.total }}</strong></article><article><span>计划回款</span><strong>{{ money(summary.total_receivable) }}</strong></article><article><span>实际已回款</span><strong class="success">{{ money(summary.total_received) }}</strong></article><article><span>待回款</span><strong class="warn">{{ money(summary.outstanding) }}</strong></article><article><span>最大资金缺口</span><strong class="danger">{{ money(summary.funding_gap) }}</strong></article></section>
    <section class="cashflow-guidance"><el-icon><Warning /></el-icon><div><strong>测算口径提示</strong><span>按计划回款与采购、专项、人员、保函等支出自动计算累计现金流；负现金流按年化利率估算垫资成本。实际回款只用于经营跟踪，不会覆盖原计划。</span></div></section>
    <section v-if="history?.project_risks.length" class="project-risk-panel"><header><div><p>项目回款优先级</p><h2>先定位具体项目，再进入区域与客户规律分析</h2></div><span>按待回金额、风险节点和回款达成率综合排序</span></header><div class="project-risk-list"><article v-for="project in history.project_risks.slice(0, 6)" :key="project.project_code || project.name"><div class="project-risk-title"><strong>{{ project.name }}</strong><small>{{ project.project_code || '未填写项目编码' }}</small></div><span>{{ project.region }} · {{ project.customer }}</span><div class="project-risk-metrics"><em>待回 {{ money(project.unpaid) }}</em><b>达成 {{ project.received_rate }}%</b><i v-if="project.difficult || project.long_term">{{ project.difficult ? '疑难' : '' }}{{ project.difficult && project.long_term ? ' · ' : '' }}{{ project.long_term ? '长账龄' : '' }}</i></div></article></div></section>
    <section v-if="history?.summary.records" class="history-panel"><header><div><p>历史回款规律 · {{ history.source_name }}</p><h2>用 {{ history.summary.records.toLocaleString() }} 条节点，为新项目测算提供参考</h2></div><div class="history-actions"><span>整体回款达成率 <b>{{ history.summary.received_rate }}%</b></span><el-button plain type="primary" @click="openHistoryEditor">编辑历史数据</el-button></div></header><div class="history-stats"><div><span>历史项目</span><b>{{ history.summary.projects }}</b></div><div><span>历史已回款</span><b>{{ money(history.summary.received_amount) }}</b></div><div><span>历史待回款</span><b class="cashflow-warn">{{ money(history.summary.unpaid_amount) }}</b></div><div><span>平均回款周期</span><b>{{ history.summary.average_collection_days == null ? '—' : `${history.summary.average_collection_days} 天` }}</b></div></div><div class="history-charts"><article class="status-chart"><h3>回款状态结构</h3><div class="status-chart__body"><div class="status-donut" :style="{ background: statusGradient }"><span><b>{{ history.summary.received_rate }}%</b><small>已达成</small></span></div><div class="status-legend"><div v-for="(row, index) in history.by_status" :key="row.name"><i :style="{ background: chartColors[index % chartColors.length] }"></i><span>{{ row.name }}</span><b>{{ money(row.planned) }}</b></div></div></div></article><article><h3>区域待回款对比</h3><div class="horizontal-chart"><div v-for="row in history.by_region.slice(0, 6)" :key="row.name" class="horizontal-chart__row"><div><b>{{ row.name }}</b><span>{{ money(row.unpaid) }}</span></div><p><i :style="{ width: `${row.unpaid / maxRegionUnpaid * 100}%` }"></i></p><small>回款达成 {{ row.received_rate }}%</small></div></div></article><article><h3>年度回款趋势</h3><div class="year-chart"><div v-for="row in history.by_year.slice(-8)" :key="row.name" class="year-chart__item"><div class="year-chart__bars"><i class="planned" :style="{ height: `${row.planned / maxYearAmount * 100}%` }"></i><i class="received" :style="{ height: `${row.received / maxYearAmount * 100}%` }"></i></div><b>{{ row.name }}</b><small>{{ row.received_rate }}%</small></div></div><p class="chart-note"><i></i>计划回款 <i class="received"></i>实际回款</p></article></div><article class="customer-profiles"><div class="customer-profiles__head"><div><p>客户回款画像</p><h3>用客户历史特性指导资金测算</h3></div><span>输入同名客户后，建议会自动带入测算表</span></div><div class="customer-profiles__table"><div class="customer-profile__row customer-profile__row--head"><span>客户</span><span>历史特性</span><span>回款表现</span><span>测算建议</span></div><div v-for="profile in history.customer_profiles.slice(0, 8)" :key="profile.name" class="customer-profile__row"><strong>{{ profile.name }}</strong><span><em v-for="trait in profile.traits" :key="trait">{{ trait }}</em></span><span>达成 {{ profile.received_rate }}%<br>{{ profile.average_collection_days == null ? '无周期样本' : `平均 ${profile.average_collection_days} 天` }}</span><p>{{ profile.recommendation }}</p></div></div></article><div class="history-dimensions"><article><h3>区域规律</h3><div v-for="row in history.by_region.slice(0, 4)" :key="row.name" class="history-row"><b>{{ row.name }}</b><span>达成 {{ row.received_rate }}% · 待回 {{ money(row.unpaid) }}</span></div></article><article><h3>回款性质规律</h3><div v-for="row in history.by_project_type.slice(0, 4)" :key="row.name" class="history-row"><b>{{ row.name }}</b><span>达成 {{ row.received_rate }}% · 待回 {{ money(row.unpaid) }}</span></div></article><article><h3>资金规模规律</h3><div v-for="row in history.by_scale" :key="row.name" class="history-row"><b>{{ row.name }}</b><span>达成 {{ row.received_rate }}% · 待回 {{ money(row.unpaid) }}</span></div></article></div></section>
    <section v-if="history?.customer_profiles.length" class="customer-quant-dashboard"><header><div><p>客户画像量化基准</p><h3>将账期、风险和回款折算系数直接带入资金测算</h3></div><span>账期按合同日至实际回款日统计；计划偏差将在补录应收日期后自动纳入</span></header><div class="customer-quant-grid"><article v-for="profile in history.customer_profiles.slice(0, 6)" :key="profile.name"><b>{{ profile.name }}</b><div><span>账期 P50 / P75</span><strong>{{ profile.median_collection_days == null ? '—' : `${profile.median_collection_days} / ${profile.p75_collection_days} 天` }}</strong></div><div><span>资金风险</span><strong :class="profile.cashflow_risk_level === '高' ? 'cashflow-danger' : profile.cashflow_risk_level === '中' ? 'cashflow-warn' : 'success'">{{ profile.cashflow_risk_score }} 分 · {{ profile.cashflow_risk_level }}</strong></div><div><span>建议回款折算</span><strong>{{ Math.round(profile.recommended_collection_factor * 100) }}%</strong></div><small>{{ profile.schedule_sample_count ? `按期率 ${profile.on_time_collection_rate}% · 偏差中位 ${profile.median_schedule_variance_days} 天` : '暂无应收计划日期样本' }}</small></article></div></section>
    <section class="cashflow-steps"><article><b>1. 先定回款</b><span>按合同约定拆分首款、到货、验收、质保等回款节点，登记计划金额与日期。</span></article><article><b>2. 再排支出</b><span>同步录入采购、专项、人员、保函和其他支出，按实际付款节奏安排日期。</span></article><article><b>3. 看资金缺口</b><span>重点处理累计现金流为负的时间段，调整账期、回款优先级或垫资方案。</span></article></section>
    <section class="cashflow-groups"><article><h3>区域回款概览</h3><div v-if="byRegion.length" class="group-list"><div v-for="row in byRegion" :key="row.name"><b>{{ row.name }}</b><span>{{ row.projects }} 个项目 · 待回 {{ money(row.outstanding) }}</span><em>缺口 {{ money(row.funding_gap) }}</em></div></div><el-empty v-else description="暂无区域资金数据" :image-size="52" /></article><article><h3>客户回款优先级</h3><div v-if="byCustomer.length" class="group-list"><div v-for="row in byCustomer.slice(0, 5)" :key="row.name"><b>{{ row.name }}</b><span>{{ row.projects }} 个项目 · 待回 {{ money(row.outstanding) }}</span><em>已回 {{ money(row.received) }}</em></div></div><el-empty v-else description="暂无客户资金数据" :image-size="52" /></article></section>
    <section class="cashflow-table"><el-table :data="filteredItems" empty-text="暂无资金测算，点击“新建资金测算”开始。"><el-table-column prop="project_name" label="项目" min-width="180"><template #default="{ row }"><strong>{{ row.project_name }}</strong><small>{{ row.project_code || row.owner || '未填写编码 / 负责人' }}</small></template></el-table-column><el-table-column prop="region" label="区域" width="94"/><el-table-column prop="customer" label="客户" min-width="130"/><el-table-column label="计划 / 已回" min-width="170"><template #default="{ row }">{{ money(row.summary.total_receivable) }} / {{ money(row.summary.total_received) }}</template></el-table-column><el-table-column label="待回款" min-width="120"><template #default="{ row }"><span class="cashflow-warn">{{ money(row.summary.outstanding) }}</span></template></el-table-column><el-table-column label="资金缺口" min-width="120"><template #default="{ row }"><span class="cashflow-danger">{{ money(row.summary.funding_gap) }}</span></template></el-table-column><el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">查看</el-button><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row.id)">删除</el-button></template></el-table-column></el-table></section>
    <el-dialog v-model="dialog" :title="form.id ? '编辑资金测算' : '新建资金测算'" width="min(1180px,96vw)" top="4vh"><el-form label-position="top"><el-row :gutter="14"><el-col :xs="24" :sm="12" :md="8"><el-form-item label="项目名称"><el-input v-model="form.project_name" placeholder="例如：金义东线续保服务"/></el-form-item></el-col><el-col :xs="12" :sm="6" :md="4"><el-form-item label="区域"><el-select v-model="form.region" style="width:100%"><el-option v-for="x in regions" :key="x" :label="x" :value="x"/></el-select></el-form-item></el-col><el-col :xs="12" :sm="6" :md="4"><el-form-item label="客户"><el-input v-model="form.customer"/></el-form-item></el-col><el-col :xs="12" :sm="6" :md="4"><el-form-item label="负责人"><el-input v-model="form.owner"/></el-form-item></el-col><el-col :xs="12" :sm="6" :md="4"><el-form-item label="年化资金成本"><el-input-number v-model="form.annual_rate" :min="0" :max="1" :step="0.005" :precision="3" style="width:100%"/><small>0.06 = 6%</small></el-form-item></el-col></el-row>
      <div v-if="formHistoryHint" class="form-history-hint"><el-icon><Warning /></el-icon><span>历史参考：{{ formHistoryHint }}</span></div><div class="entry-title"><div><b>资金节点</b><span>计划回款用于测算；实际已回款用于回款跟踪。金额均为元。</span></div><el-button text type="primary" :icon="Plus" @click="addEntry">增加节点</el-button></div><div class="entry-scroll"><table class="entry-table"><thead><tr><th>日期</th><th>里程碑</th><th>计划回款</th><th>实际已回</th><th>采购付款</th><th>专项采购</th><th>专项报销</th><th>人员</th><th>其他 / 贴现</th><th>保函 / 保证金</th><th></th></tr></thead><tbody><tr v-for="(entry,index) in form.entries" :key="entry.id || index"><td><el-date-picker v-model="entry.date" type="date" value-format="YYYY-MM-DD" style="width:130px"/></td><td><el-input v-model="entry.milestone" style="min-width:130px" placeholder="如：验收回款"/></td><td><el-input-number v-model="entry.receivable" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.received" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.procurement" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.special_procurement" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.reimbursement" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.personnel" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.other" :min="0" controls-position="right"/></td><td><el-input-number v-model="entry.guarantee" :min="0" controls-position="right"/></td><td><el-button link type="danger" :disabled="form.entries.length===1" @click="removeEntry(index)">移除</el-button></td></tr></tbody></table></div><el-form-item label="测算备注"><el-input v-model="form.note" type="textarea" :rows="2" placeholder="记录回款条件、账期、风险假设或催收动作。"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">保存并计算</el-button></template></el-dialog>
    <el-dialog v-model="detailVisible" title="资金测算明细" width="min(1080px,96vw)"><template v-if="detail"><section class="detail-summary"><span>{{ detail.project_name }} · {{ detail.region }} · {{ detail.customer || '未填写客户' }}</span><b>预计资金缺口 {{ money(detail.summary.funding_gap) }}，垫资成本 {{ money(detail.summary.funding_cost) }}</b></section><el-table :data="detail.entries"><el-table-column prop="date" label="日期" width="112"/><el-table-column prop="milestone" label="节点" min-width="130"/><el-table-column prop="receivable" label="计划回款"><template #default="{row}">{{ money(row.receivable) }}</template></el-table-column><el-table-column prop="received" label="实际已回"><template #default="{row}">{{ money(row.received) }}</template></el-table-column><el-table-column prop="payment" label="付款"><template #default="{row}">{{ money(row.payment || 0) }}</template></el-table-column><el-table-column prop="net_cashflow" label="单期现金流"><template #default="{row}">{{ money(row.net_cashflow || 0) }}</template></el-table-column><el-table-column prop="cumulative_cashflow" label="累计现金流"><template #default="{row}"><span :class="(row.cumulative_cashflow || 0)<0?'cashflow-danger':''">{{ money(row.cumulative_cashflow || 0) }}</span></template></el-table-column></el-table></template></el-dialog>
